#![allow(clippy::unwrap_used)]
// Conformance tests that replay fixtures generated by gen.mjs against the Rust parsers.

use review_bundle::discovery;
use review_bundle::findings;
use review_bundle::patch;
use serde::Deserialize;
use std::collections::BTreeMap;

// --- Patch fixtures ---

#[derive(Deserialize)]
struct PatchFixture {
    name: String,
    input: String,
    expected: PatchExpected,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct PatchExpected {
    files: Vec<patch::PatchFile>,
    changed_lines: BTreeMap<String, Vec<u32>>,
}

#[test]
fn test_patch_fixtures() {
    let data = include_str!("fixtures/patch_fixtures.json");
    let fixtures: Vec<PatchFixture> =
        serde_json::from_str(data).expect("failed to parse patch_fixtures.json");

    assert!(
        fixtures.len() >= 50,
        "expected at least 50 patch fixtures, got {}",
        fixtures.len()
    );

    let mut pass = 0;
    let mut fail = 0;
    let mut failures = Vec::new();

    for fixture in &fixtures {
        let files = patch::parse_patch(&fixture.input);
        let changed = patch::changed_lines(&files);

        let files_match = files == fixture.expected.files;
        let changed_match = changed == fixture.expected.changed_lines;

        if files_match && changed_match {
            pass += 1;
        } else {
            fail += 1;
            if !files_match {
                failures.push(format!(
                    "FAIL [{}]: files mismatch\n  got {} files, expected {}\n  got: {:?}\n  exp: {:?}",
                    fixture.name,
                    files.len(),
                    fixture.expected.files.len(),
                    files.iter().map(|f| (&f.path, &f.tag, f.added, f.removed, f.rows.len())).collect::<Vec<_>>(),
                    fixture.expected.files.iter().map(|f| (&f.path, &f.tag, f.added, f.removed, f.rows.len())).collect::<Vec<_>>()
                ));
            }
            if !changed_match {
                failures.push(format!(
                    "FAIL [{}]: changedLines mismatch\n  got: {:?}\n  exp: {:?}",
                    fixture.name, changed, fixture.expected.changed_lines
                ));
            }
        }
    }

    if fail > 0 {
        for f in &failures {
            eprintln!("{}", f);
        }
        panic!("{} of {} patch fixtures failed", fail, pass + fail);
    }
    eprintln!("All {} patch fixtures passed", pass);
}

