// --- Discovery fixtures ---

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct DiscoveryFixture {
    name: String,
    files: Vec<String>,
    expected_document: Option<String>,
    expected_patches: Vec<String>,
}

#[test]
fn test_discovery_fixtures() {
    let data = include_str!("fixtures/discovery_fixtures.json");
    let fixtures: Vec<DiscoveryFixture> =
        serde_json::from_str(data).expect("failed to parse discovery_fixtures.json");

    let mut pass = 0;
    let mut fail = 0;
    let mut failures = Vec::new();

    for fixture in &fixtures {
        let file_refs: Vec<&str> = fixture.files.iter().map(|s| s.as_str()).collect();
        let doc = discovery::document_of(&file_refs);
        let patches = discovery::patches_of(&file_refs);

        let doc_match = doc == fixture.expected_document;
        let patches_match = patches == fixture.expected_patches;

        if doc_match && patches_match {
            pass += 1;
        } else {
            fail += 1;
            if !doc_match {
                failures.push(format!(
                    "FAIL [{}]: document mismatch: got {:?}, expected {:?}",
                    fixture.name, doc, fixture.expected_document
                ));
            }
            if !patches_match {
                failures.push(format!(
                    "FAIL [{}]: patches mismatch: got {:?}, expected {:?}",
                    fixture.name, patches, fixture.expected_patches
                ));
            }
        }
    }

    if fail > 0 {
        for f in &failures {
            eprintln!("{}", f);
        }
        panic!("{} of {} discovery fixtures failed", fail, pass + fail);
    }
    eprintln!("All {} discovery fixtures passed", pass);
}

// --- Findings fixtures ---

#[derive(Deserialize)]
struct FindingsFixture {
    name: String,
    format: String,
    input: String,
    expected: Vec<findings::Finding>,
}

#[test]
fn test_findings_fixtures() {
    let data = include_str!("fixtures/findings_fixtures.json");
    let fixtures: Vec<FindingsFixture> =
        serde_json::from_str(data).expect("failed to parse findings_fixtures.json");

    let mut pass = 0;
    let mut fail = 0;
    let mut failures = Vec::new();

    for fixture in &fixtures {
        let result = match fixture.format.as_str() {
            "json" => findings::read_findings_json(&fixture.input),
            "jsonl" => findings::read_findings_jsonl(&fixture.input),
            other => panic!("unknown format: {}", other),
        };

        match result {
            Ok(findings_list) => {
                // Compare by re-serializing to serde_json::Value since the Finding struct
                // might have slightly different field presence for optional fields
                let got: serde_json::Value = serde_json::to_value(&findings_list).unwrap();
                let exp: serde_json::Value = serde_json::to_value(&fixture.expected).unwrap();
                if got == exp {
                    pass += 1;
                } else {
                    fail += 1;
                    failures.push(format!(
                        "FAIL [{}]: findings mismatch\n  got:  {}\n  exp:  {}",
                        fixture.name,
                        serde_json::to_string_pretty(&got).unwrap(),
                        serde_json::to_string_pretty(&exp).unwrap()
                    ));
                }
            }
            Err(e) => {
                fail += 1;
                failures.push(format!("FAIL [{}]: parse error: {}", fixture.name, e));
            }
        }
    }

    if fail > 0 {
        for f in &failures {
            eprintln!("{}", f);
        }
        panic!("{} of {} findings fixtures failed", fail, pass + fail);
    }
    eprintln!("All {} findings fixtures passed", pass);
}
